1	/**
2	 * @module features/tv-dashboard/model/useTvRealtime
3	 *
4	 * Assina canais Supabase Realtime nas tabelas `movimentacoes`, `estoque` e
5	 * `alertas_estoque` (mesmo padrão de `features/dashboard/useRealtimeUpdates`)
6	 * e invalida as query keys do painel TV para refletir mudanças antes do
7	 * próximo ciclo de polling.
8	 *
9	 * As invalidações são debounced (janela de 2s) para não estourar refetches
10	 * durante rajadas de bipagem (conferência de expedição gera dezenas de
11	 * INSERTs em sequência).
12	 */
13	
14	import { useEffect, useRef } from 'react';
15	import { useQueryClient } from '@tanstack/react-query';
16	import { supabase } from '@/integrations/supabase/client';
17	import { tvDashboardKeys } from './useTvDashboardData';
18	
19	/** Janela de debounce das invalidações disparadas pelo Realtime (ms). */
20	const REALTIME_DEBOUNCE_MS = 2_000;
21	
22	/**
23	 * Subscreve `postgres_changes` em movimentações/estoque/alertas e invalida
24	 * as queries relevantes do painel TV:
25	 * - `movimentacoes` → heartbeat de movimentações (+ expedições da fábrica);
26	 * - `estoque` / `alertas_estoque` → alertas de estoque (faixa de exceções).
27	 *
28	 * Remove os canais e cancela timers pendentes ao desmontar.
29	 */
30	export function useTvRealtime(): void {
31	  const queryClient = useQueryClient();
32	  // Timers por grupo de invalidação (debounce independente)
33	  const movementTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
34	  const stockTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
35	
36	  useEffect(() => {
37	    const invalidateMovements = () => {
38	      if (movementTimer.current) return; // já agendado nesta janela
39	      movementTimer.current = setTimeout(() => {
40	        movementTimer.current = null;
41	        queryClient.invalidateQueries({ queryKey: tvDashboardKeys.movements() });
42	      }, REALTIME_DEBOUNCE_MS);
43	    };
44	
45	    const invalidateStock = () => {
46	      if (stockTimer.current) return;
47	      stockTimer.current = setTimeout(() => {
48	        stockTimer.current = null;
49	        queryClient.invalidateQueries({ queryKey: tvDashboardKeys.stock() });
50	      }, REALTIME_DEBOUNCE_MS);
51	    };
52	
53	    const movementsChannel = supabase
54	      .channel('tv-movements-changes')
55	      .on(
56	        'postgres_changes',
57	        { event: '*', schema: 'public', table: 'movimentacoes' },
58	        invalidateMovements,
59	      )
60	      .subscribe();
61	
62	    const stockChannel = supabase
63	      .channel('tv-stock-changes')
64	      .on(
65	        'postgres_changes',
66	        { event: '*', schema: 'public', table: 'estoque' },
67	        invalidateStock,
68	      )
69	      .subscribe();
70	
71	    const alertsChannel = supabase
72	      .channel('tv-alerts-changes')
73	      .on(
74	        'postgres_changes',
75	        { event: '*', schema: 'public', table: 'alertas_estoque' },
76	        invalidateStock,
77	      )
78	      .subscribe();
79	
80	    return () => {
81	      if (movementTimer.current) clearTimeout(movementTimer.current);
82	      if (stockTimer.current) clearTimeout(stockTimer.current);
83	      movementTimer.current = null;
84	      stockTimer.current = null;
85	      supabase.removeChannel(movementsChannel);
86	      supabase.removeChannel(stockChannel);
87	      supabase.removeChannel(alertsChannel);
88	    };
89	  }, [queryClient]);
90	}
