55	export function NotificationBell() {
56	  const navigate = useNavigate();
57	  const isRhMaster = useIsRhMaster();
58	  const [items, setItems] = useState<NotificacaoMaster[]>([]);
59	  const [unread, setUnread] = useState(0);
60	
61	  const fetch = async () => {
62	    const { data } = await supabase
63	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
64	      .from('notificacoes_master' as any)
65	      .select('*')
66	      .order('created_at', { ascending: false })
67	      .limit(20);
68	    const arr = (data ?? []) as unknown as NotificacaoMaster[];
69	    setItems(arr);
70	    setUnread(arr.filter((n) => !n.lida).length);
71	  };
72	
73	  useEffect(() => {
74	    if (!isRhMaster) return;
75	    fetch();
76	
77	    // Realtime
78	    const channel = supabase
79	      .channel('notificacoes_master_bell')
80	      .on(
81	        'postgres_changes',
82	        { event: '*', schema: 'public', table: 'notificacoes_master' },
83	        () => fetch(),
84	      )
85	      .subscribe();
86	
87	    return () => {
88	      supabase.removeChannel(channel);
89	    };
90	    // eslint-disable-next-line react-hooks/exhaustive-deps
91	  }, []);
92	
93	  const marcarLida = async (id: string) => {
94	    await supabase
95	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
96	      .from('notificacoes_master' as any)
97	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
98	      .update({ lida: true, lida_em: new Date().toISOString() } as any)
99	      .eq('id', id);
100	  };
101	
102	  const marcarTodas = async () => {
103	    await supabase
104	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
105	      .from('notificacoes_master' as any)
106	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
107	      .update({ lida: true, lida_em: new Date().toISOString() } as any)
108	      .eq('lida', false);
109	  };
110	
111	  if (!isRhMaster) return null;
112	
113	  return (
114	    <DropdownMenu>
115	      <DropdownMenuTrigger asChild>
116	        <Button data-mia-action="notifica-es"
117	          variant="ghost"
118	          size="icon"
119	          className="relative h-9 w-9 rounded-xl hover:bg-[#57715B]/10"
120	          aria-label="Notificações"
121	        >
122	          <Bell className="h-5 w-5 text-[#57715B] dark:text-[#E6DCCF]" />
123	          {unread > 0 && (
124	            <span className="absolute -top-0.5 -right-0.5 h-4 min-w-4 px-1 rounded-full bg-red-500 text-white text-[10px] font-bold flex items-center justify-center">
125	              {unread > 9 ? '9+' : unread}
126	            </span>
127	          )}
128	        </Button>
129	      </DropdownMenuTrigger>
130	      <DropdownMenuContent
131	        align="end"
132	        className="w-80 max-h-[480px] overflow-y-auto rounded-2xl border-[#57715B]/10 bg-white/95 dark:bg-zinc-900/95 backdrop-blur-xl p-0"
133	      >
134	        <div className="flex items-center justify-between p-3 border-b border-[#57715B]/10">
135	          <p className="font-bold text-sm text-[#2D362E] dark:text-[#E6DCCF]">
136	            Notificações
137	            {unread > 0 && (
138	              <span className="ml-2 text-xs text-red-600">{unread} não lidas</span>
139	            )}
140	          </p>
141	          {unread > 0 && (
142	            <button
143	              onClick={marcarTodas}
144	              className="text-xs text-[#57715B] hover:underline"
145	            >
146	              Marcar todas
147	            </button>
148	          )}
149	        </div>
150	        {items.length === 0 ? (
151	          <div className="py-8 text-center text-sm text-[#8C7B6D] dark:text-[#9BA59C]">
152	            Sem notificações
153	          </div>
154	        ) : (
155	          <div className="divide-y divide-[#57715B]/5">
156	            {items.map((n) => {
157	              const Icon = TIPO_ICON[n.tipo] ?? Bell;
158	              return (
159	                <button
160	                  key={n.id}
161	                  onClick={() => {
162	                    if (!n.lida) marcarLida(n.id);
163	                    navigate(TIPO_ROUTE[n.tipo] ?? '/funcionarios');
164	                  }}
165	                  className={`w-full text-left p-3 hover:bg-[#57715B]/5 transition-colors ${
166	                    !n.lida ? 'bg-[#57715B]/5' : ''
167	                  }`}
168	                >
169	                  <div className="flex items-start gap-2">
170	                    <Icon className="h-4 w-4 text-[#57715B] shrink-0 mt-0.5" />
171	                    <div className="flex-1 min-w-0">
172	                      <p className={`text-sm truncate ${!n.lida ? 'font-bold' : ''} text-[#2D362E] dark:text-[#E6DCCF]`}>
173	                        {n.titulo}
174	                      </p>
175	                      {n.descricao && (
176	                        <p className="text-xs text-[#8C7B6D] dark:text-[#9BA59C] line-clamp-2 mt-0.5">
177	                          {n.descricao}
178	                        </p>
179	                      )}
180	                      <p className="text-[10px] text-[#8C7B6D]/70 mt-1 font-mono">
181	                        {new Date(n.created_at).toLocaleString('pt-BR')}
182	                      </p>
183	                    </div>
184	                    {!n.lida && (
185	                      <span className="h-2 w-2 rounded-full bg-red-500 mt-2 shrink-0" />
186	                    )}
187	                  </div>
188	                </button>
189	              );
190	            })}
191	          </div>
192	        )}
193	      </DropdownMenuContent>
194	    </DropdownMenu>
195	  );
196	}
