19	interface PermissionsContextType {
20	  permissions: Permission[];
21	  userRole: UserRole | null;
22	  loading: boolean;
23	  hasPermission: (permissionName: string) => boolean;
24	  hasAnyPermission: (permissionNames: string[]) => boolean;
25	  isAdmin: () => boolean;
26	  canAccessModule: (module: string) => boolean;
27	  refreshPermissions: () => Promise<void>;
