/**
 * @module features/gestao/model/types
 * Tipos compartilhados da feature gestao-operacional-n1.
 * Derivados dos contratos das tabelas `eventos_operacionais` e `gestao_alertas`
 * (ver ADR-20260605-gestao-operacional-n1.md, seção D1).
 */

import type { Database } from '@/integrations/supabase/types';

/** Row canônica do bus de eventos. */
export type EventoOperacional =
  Database['public']['Tables']['eventos_operacionais']['Row'];

/** Row canônica de alerta de gestão. */
export type GestaoAlerta =
  Database['public']['Tables']['gestao_alertas']['Row'];

/** Setores ativos na 1ª onda. */
export type Setor = 'logistica' | 'producao' | 'estoque';

/** Severidade de alerta — mesma CHECK constraint do banco. */
export type Severidade = 'critica' | 'alta' | 'media';

/** Status de alerta — mesma CHECK constraint do banco. */
export type AlertaStatus = 'aberto' | 'reconhecido' | 'resolvido';

/** Alerta tipado com severidade e status inferidos. */
export type GestaoAlertaTyped = Omit<GestaoAlerta, 'severidade' | 'status'> & {
  severidade: Severidade;
  status: AlertaStatus;
};

/** KPIs de fluxo do dia: derivados do bus `eventos_operacionais`. */
export interface FluxoKpis {
  /** Contagem por tipo_evento hoje. */
  countsByTipo: Record<string, number>;
  /** Último evento recebido (para "última atualização"). */
  lastEventAt: string | null;
}

/** Deep-link para a tela N0 correspondente. */
export interface DeepLink {
  label: string;
  path: string;
}

/** Configuração de um setor no registry. */
export interface SetorConfig {
  setor: Setor;
  permission: string;
  titulo: string;
  subtitulo: string;
  /** Ícone LucideIcon component. */
  icon: React.ComponentType<{ className?: string }>;
  /** Componente de KPIs específico do setor. */
  KpisComponent: React.ComponentType<KpisComponentProps>;
  deepLinks: DeepLink[];
}

/** Props injetadas no componente de KPIs de cada setor. */
export interface KpisComponentProps {
  setor: Setor;
  lojaId: number | null;
}

/**
 * @module features/gestao/model/setorConfig
 *
 * Registry central de setores: setor → permission, título, ícone,
 * componente de KPIs e deep-links N0.
 *
 * Adicionar setor na onda 2 = 1 entrada aqui + 1 componente de KPIs.
 * Não altera nenhum outro arquivo de infra (ADR D5, critério extensível).
 */

import { Truck, Factory, Boxes } from 'lucide-react';
import { LogisticaKpis } from '../ui/setores/LogisticaKpis';
import { ProducaoKpis } from '../ui/setores/ProducaoKpis';
import { EstoqueKpis } from '../ui/setores/EstoqueKpis';
import type { Setor, SetorConfig } from './types';

const CONFIG: Record<Setor, SetorConfig> = {
  logistica: {
    setor: 'logistica',
    permission: 'view_gestao_logistica',
    titulo: 'Logística',
    subtitulo: 'Expedição & Requisições',
    icon: Truck,
    KpisComponent: LogisticaKpis,
    deepLinks: [
      { label: 'Torre de Controle', path: '/logistica/control-tower' },
      { label: 'Requisições', path: '/requisicao' },
      { label: 'Logística', path: '/logistica' },
    ],
  },
  producao: {
    setor: 'producao',
    permission: 'view_gestao_producao',
    titulo: 'Produção',
    subtitulo: 'Fábrica & Lançamentos',
    icon: Factory,
    KpisComponent: ProducaoKpis,
    deepLinks: [
      { label: 'Produção Diária', path: '/producao-diaria' },
      { label: 'Fichas Técnicas', path: '/producao/fichas-tecnicas' },
    ],
  },
  estoque: {
    setor: 'estoque',
    permission: 'view_gestao_estoque',
    titulo: 'Estoque',
    subtitulo: 'Inventário & Movimentações',
    icon: Boxes,
    KpisComponent: EstoqueKpis,
    deepLinks: [
      { label: 'Movimentações', path: '/movimentacoes' },
      { label: 'Produtos', path: '/produtos' },
      { label: 'Pronta Entrega', path: '/pronta-entrega' },
    ],
  },
};

/** Retorna a configuração de um setor pelo slug. Lança se o setor não existe. */
export function getSetorConfig(setor: Setor): SetorConfig {
  const cfg = CONFIG[setor];
  if (!cfg) {
    throw new Error(`[gestao] Setor desconhecido: "${setor}". Adicionar entrada em setorConfig.ts.`);
  }
  return cfg;
}

/** Array com todos os setores ativos, na ordem de exibição. */
export const SETORES_ATIVOS: Setor[] = ['logistica', 'producao', 'estoque'];

/** Verifica se a permission string corresponde a algum setor de gestão. */
export function isGestaoPermission(perm: string): boolean {
  return SETORES_ATIVOS.some((s) => CONFIG[s].permission === perm);
}

/** Retorna todas as permissions de gestão (para o badge do sino). */
export function getAllGestaoPermissions(): string[] {
  return SETORES_ATIVOS.map((s) => CONFIG[s].permission);
}

/**
 * @module features/gestao/model/useEventosFeed
 *
 * Query + Realtime debounce 2s para o feed de `eventos_operacionais`.
 * Clona o padrão `useTvRealtime` (debounce de 2s durante rajadas de bipagem).
 *
 * Paginação por cursor (id < último) conforme ADR D5.
 * Limite inicial: 50 eventos. Botão "carregar anteriores" decrementa o cursor.
 */

import { useEffect, useRef, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type { Setor, EventoOperacional } from './types';

const REALTIME_DEBOUNCE_MS = 2_000;
const PAGE_SIZE = 50;

interface UseEventosFeedOptions {
  setor: Setor;
  /** loja_id do usuário (null = admin, sem filtro adicional — RLS já escopa). */
  lojaId: number | null;
}

interface UseEventosFeedResult {
  eventos: EventoOperacional[];
  isLoading: boolean;
  /** Há mais eventos antes do cursor atual. */
  hasMore: boolean;
  /** Carrega a próxima página (cursor-based). */
  loadMore: () => void;
}

export const eventosKeys = {
  feed: (setor: Setor, cursorId: number | null) =>
    ['gestao', 'eventos', setor, cursorId] as const,
};

async function fetchEventos(
  setor: Setor,
  cursorId: number | null,
): Promise<EventoOperacional[]> {
  let query = supabase
    .from('eventos_operacionais')
    .select('*')
    .eq('setor', setor)
    .order('id', { ascending: false })
    .limit(PAGE_SIZE + 1); // +1 para detectar hasMore

  if (cursorId !== null) {
    query = query.lt('id', cursorId);
  }

  const { data, error } = await query;
  if (error) throw error;
  return (data ?? []) as EventoOperacional[];
}

/**
 * Mantém a lista de eventos acumulada (novas no topo, antigas no fundo)
 * e gerencia o cursor para paginação histórica.
 */
export function useEventosFeed({
  setor,
  lojaId: _lojaId, // RLS já escopa — mantemos para sinalizar o escopo ao leitor
}: UseEventosFeedOptions): UseEventosFeedResult {
  const queryClient = useQueryClient();
  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Cursor da página mais antiga carregada (null = primeira página)
  const [cursor, setCursor] = useState<number | null>(null);
  // Todos os eventos acumulados (mais recentes primeiro)
  const [allEventos, setAllEventos] = useState<EventoOperacional[]>([]);
  // Rastreia se a query já foi inicializada (para não sobrescrever realtime prepends)
  const initialized = useRef(false);

  const queryKey = eventosKeys.feed(setor, cursor);

  const { data, isLoading } = useQuery({
    queryKey,
    queryFn: () => fetchEventos(setor, cursor),
    staleTime: 30_000,
  });

  // Ao receber nova página, acumular no array
  useEffect(() => {
    if (!data) return;
    const page = data.slice(0, PAGE_SIZE); // remove o sentinela +1
    if (!initialized.current) {
      setAllEventos(page);
      initialized.current = true;
    } else {
      // Paginação histórica: append no fundo (eventos mais antigos)
      setAllEventos((prev) => {
        const ids = new Set(prev.map((e) => e.id));
        const newOnes = page.filter((e) => !ids.has(e.id));
        return [...prev, ...newOnes];
      });
    }
  }, [data]);

  // Realtime: prepend novos eventos com debounce 2s
  useEffect(() => {
    const invalidate = () => {
      if (debounceTimer.current) return;
      debounceTimer.current = setTimeout(() => {
        debounceTimer.current = null;
        // Busca os eventos mais recentes (sem cursor = topo)
        fetchEventos(setor, null).then((fresh) => {
          setAllEventos((prev) => {
            const ids = new Set(prev.map((e) => e.id));
            const newOnes = fresh
              .slice(0, PAGE_SIZE)
              .filter((e) => !ids.has(e.id));
            if (newOnes.length === 0) return prev;
            return [...newOnes, ...prev];
          });
        });
        // Invalida também para manter o cache consistente
        queryClient.invalidateQueries({
          queryKey: ['gestao', 'eventos', setor],
        });
      }, REALTIME_DEBOUNCE_MS);
    };

    const channel = supabase
      .channel(`gestao-eventos-${setor}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'eventos_operacionais',
          filter: `setor=eq.${setor}`,
        },
        invalidate,
      )
      .subscribe();

    return () => {
      if (debounceTimer.current) {
        clearTimeout(debounceTimer.current);
        debounceTimer.current = null;
      }
      supabase.removeChannel(channel);
    };
  }, [setor, queryClient]);

  const hasMore = (data?.length ?? 0) > PAGE_SIZE;

  const loadMore = () => {
    if (allEventos.length === 0) return;
    const oldestId = allEventos[allEventos.length - 1].id;
    setCursor(oldestId);
  };

  return { eventos: allEventos, isLoading, hasMore, loadMore };
}

/**
 * @module features/gestao/model/useGestaoAlertas
 *
 * Alertas vivos (aberto + reconhecido) de um setor via Realtime.
 * Mutations: reconhecer (status → 'reconhecido') e resolver (status → 'resolvido',
 * resolucao → 'manual').
 *
 * RLS do banco já filtra por loja e permission — o cliente não precisa
 * filtrar adicionalmente por loja_id.
 */

import { useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/shared/hooks/useAuth';
import type { Setor, GestaoAlertaTyped, AlertaStatus } from './types';

export const alertasKeys = {
  list: (setor: Setor) => ['gestao', 'alertas', setor] as const,
  bell: () => ['gestao', 'alertas', 'bell'] as const,
};

/** Busca alertas não-resolvidos de um setor. Ordenados por severidade e data. */
async function fetchAlertas(setor: Setor): Promise<GestaoAlertaTyped[]> {
  const { data, error } = await supabase
    .from('gestao_alertas')
    .select('*')
    .eq('setor', setor)
    .neq('status', 'resolvido')
    .order('created_at', { ascending: false });

  if (error) throw error;

  // Ordenar por severidade (critica > alta > media) + created_at desc
  const sevOrder: Record<string, number> = { critica: 0, alta: 1, media: 2 };
  return ((data ?? []) as GestaoAlertaTyped[]).sort((a, b) => {
    const diff =
      (sevOrder[a.severidade] ?? 9) - (sevOrder[b.severidade] ?? 9);
    if (diff !== 0) return diff;
    return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
  });
}

/** Busca count de alertas 'aberto' em todos os setores (para o sino). */
async function fetchBellCount(): Promise<number> {
  const { count, error } = await supabase
    .from('gestao_alertas')
    .select('id', { count: 'exact', head: true })
    .eq('status', 'aberto');
  if (error) throw error;
  return count ?? 0;
}

interface UseGestaoAlertasResult {
  alertas: GestaoAlertaTyped[];
  isLoading: boolean;
  reconhecer: (id: number) => Promise<void>;
  resolver: (id: number) => Promise<void>;
}

export function useGestaoAlertas(setor: Setor): UseGestaoAlertasResult {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  const { data, isLoading } = useQuery({
    queryKey: alertasKeys.list(setor),
    queryFn: () => fetchAlertas(setor),
    staleTime: 30_000,
  });

  // Realtime: reagir a INSERT e UPDATE em gestao_alertas do setor
  useEffect(() => {
    const handler = () => {
      queryClient.invalidateQueries({ queryKey: alertasKeys.list(setor) });
      queryClient.invalidateQueries({ queryKey: alertasKeys.bell() });
    };

    const channel = supabase
      .channel(`gestao-alertas-${setor}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'gestao_alertas',
          filter: `setor=eq.${setor}`,
        },
        handler,
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [setor, queryClient]);

  const updateStatus = async (
    id: number,
    patch: Partial<{ status: AlertaStatus; resolucao: string; reconhecido_por: string; reconhecido_em: string; resolvido_em: string }>,
  ) => {
    const { error } = await supabase
      .from('gestao_alertas')
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .update(patch as any)
      .eq('id', id);
    if (error) throw error;
    queryClient.invalidateQueries({ queryKey: alertasKeys.list(setor) });
    queryClient.invalidateQueries({ queryKey: alertasKeys.bell() });
  };

  const reconhecer = async (id: number) => {
    await updateStatus(id, {
      status: 'reconhecido',
      reconhecido_por: user?.id,
      reconhecido_em: new Date().toISOString(),
    });
  };

  const resolver = async (id: number) => {
    await updateStatus(id, {
      status: 'resolvido',
      resolucao: 'manual',
      resolvido_em: new Date().toISOString(),
    });
  };

  return {
    alertas: data ?? [],
    isLoading,
    reconhecer,
    resolver,
  };
}

/** Hook para o sino: conta alertas 'aberto' em todos os setores. */
export function useGestaoAlertasBell(): {
  count: number;
  isLoading: boolean;
  recentAlertas: GestaoAlertaTyped[];
} {
  const queryClient = useQueryClient();

  const { data: count = 0, isLoading } = useQuery({
    queryKey: alertasKeys.bell(),
    queryFn: fetchBellCount,
    staleTime: 30_000,
  });

  // Últimos 10 alertas abertos (todos os setores)
  const { data: recentAlertas = [] } = useQuery({
    queryKey: ['gestao', 'alertas', 'bell', 'recent'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('gestao_alertas')
        .select('*')
        .eq('status', 'aberto')
        .order('created_at', { ascending: false })
        .limit(10);
      if (error) throw error;
      return (data ?? []) as GestaoAlertaTyped[];
    },
    staleTime: 30_000,
  });

  // Realtime: qualquer mudança em gestao_alertas invalida o badge
  useEffect(() => {
    const handler = () => {
      queryClient.invalidateQueries({ queryKey: alertasKeys.bell() });
      queryClient.invalidateQueries({ queryKey: ['gestao', 'alertas', 'bell', 'recent'] });
    };

    const channel = supabase
      .channel('gestao-alertas-bell-global')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'gestao_alertas' },
        handler,
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [queryClient]);

  return { count, isLoading, recentAlertas };
}

/**
 * @module features/gestao/model/useGestaoKpis
 *
 * KPIs derivados do bus `eventos_operacionais` (fluxo: count do dia por tipo)
 * e das tabelas de domínio (estado: rupturas, mínimos, produção).
 *
 * Cada setor expõe suas próprias queries; este hook agrega o fluxo genérico
 * (counts por tipo_evento de hoje) que todos os setores usam como base.
 */

import { useEffect } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type { Setor } from './types';

export const kpisKeys = {
  fluxo: (setor: Setor) => ['gestao', 'kpis', 'fluxo', setor] as const,
  estoque: () => ['gestao', 'kpis', 'estoque'] as const,
  producao: () => ['gestao', 'kpis', 'producao'] as const,
  logistica: () => ['gestao', 'kpis', 'logistica'] as const,
};

/** Contagem de eventos de hoje por tipo_evento para um setor. */
async function fetchFluxoKpis(
  setor: Setor,
): Promise<Record<string, number>> {
  const hoje = new Date();
  hoje.setHours(0, 0, 0, 0);

  const { data, error } = await supabase
    .from('eventos_operacionais')
    .select('tipo_evento')
    .eq('setor', setor)
    .gte('criado_em', hoje.toISOString());

  if (error) throw error;

  const counts: Record<string, number> = {};
  for (const row of data ?? []) {
    counts[row.tipo_evento] = (counts[row.tipo_evento] ?? 0) + 1;
  }
  return counts;
}

/** Hook de KPIs de fluxo do dia para um setor. */
export function useFluxoKpis(setor: Setor): {
  counts: Record<string, number>;
  isLoading: boolean;
} {
  const queryClient = useQueryClient();

  const { data, isLoading } = useQuery({
    queryKey: kpisKeys.fluxo(setor),
    queryFn: () => fetchFluxoKpis(setor),
    staleTime: 60_000, // KPIs de fluxo: 1 min de cache
    refetchInterval: 5 * 60_000, // revalidar a cada 5 min
  });

  useEffect(() => {
    const handler = () => {
      queryClient.invalidateQueries({ queryKey: kpisKeys.fluxo(setor) });
    };

    const channel = supabase
      .channel(`gestao-kpis-${setor}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'eventos_operacionais',
          filter: `setor=eq.${setor}`,
        },
        handler,
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [setor, queryClient]);

  return { counts: data ?? {}, isLoading };
}

// ─── KPIs de Estado: Estoque ───────────────────────────────────────────────

export interface EstoqueEstadoKpis {
  rupturas: number;
  abaixoMinimo: number;
  isLoading: boolean;
}

/** Rupturas e abaixo-do-mínimo da loja do usuário (RLS já escopa). */
export function useEstoqueEstadoKpis(): EstoqueEstadoKpis {
  const { data, isLoading } = useQuery({
    queryKey: kpisKeys.estoque(),
    queryFn: async () => {
      // Rupturas: quantidade_atual <= 0, não oculto
      const { count: rupturas, error: e1 } = await supabase
        .from('estoque')
        .select('id', { count: 'exact', head: true })
        .lte('quantidade_atual', 0)
        .not('oculto', 'eq', true);

      // Abaixo do mínimo: quantidade_atual < quantidade_minima AND quantidade_minima > 0
      const { count: abaixoMinimo, error: e2 } = await supabase
        .from('estoque')
        .select('id', { count: 'exact', head: true })
        .gt('quantidade_minima', 0)
        // RPC ou filter expression — usar filter com rpc não disponível; aproximar:
        // Supabase .lt com coluna só funciona com constante. Usamos .filter()
        .filter('quantidade_atual', 'lt', 'quantidade_minima');

      if (e1 || e2) throw e1 ?? e2;

      return {
        rupturas: rupturas ?? 0,
        abaixoMinimo: abaixoMinimo ?? 0,
      };
    },
    staleTime: 60_000,
  });

  return {
    rupturas: data?.rupturas ?? 0,
    abaixoMinimo: data?.abaixoMinimo ?? 0,
    isLoading,
  };
}

// ─── KPIs de Estado: Produção ──────────────────────────────────────────────

export interface ProducaoRag {
  /** null = não lançada ainda; string ISO = hora do lançamento */
  lancadaEm: string | null;
  /** 'verde' | 'ambar' | 'vermelho' */
  rag: 'verde' | 'ambar' | 'vermelho';
  totalUnidades: number;
  itens: number;
}

/**
 * Classifica o status do lançamento de produção de hoje.
 * Verde = lançada; Âmbar = não lançada antes 12:00 (hora local);
 * Vermelho = não lançada depois 12:00.
 */
export function classifyProducaoRag(
  lancadaEm: string | null,
  agora: Date = new Date(),
): 'verde' | 'ambar' | 'vermelho' {
  if (lancadaEm !== null) return 'verde';
  const hora = agora.getHours() + agora.getMinutes() / 60;
  return hora < 12 ? 'ambar' : 'vermelho';
}

export function useProducaoEstadoKpis(): ProducaoRag & { isLoading: boolean } {
  const { data, isLoading } = useQuery({
    queryKey: kpisKeys.producao(),
    queryFn: async () => {
      // Busca o último evento producao.lancada de hoje
      const hoje = new Date();
      hoje.setHours(0, 0, 0, 0);

      const { data: eventos, error } = await supabase
        .from('eventos_operacionais')
        .select('payload, criado_em')
        .eq('setor', 'producao')
        .eq('tipo_evento', 'producao.lancada')
        .gte('criado_em', hoje.toISOString())
        .order('criado_em', { ascending: false })
        .limit(1);

      if (error) throw error;

      if (!eventos || eventos.length === 0) {
        return { lancadaEm: null, totalUnidades: 0, itens: 0 };
      }

      const ev = eventos[0];
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const p = ev.payload as any;
      return {
        lancadaEm: ev.criado_em,
        totalUnidades: (p?.total_unidades as number) ?? 0,
        itens: Array.isArray(p?.itens) ? (p.itens as unknown[]).length : (p?.itens as number) ?? 0,
      };
    },
    staleTime: 60_000,
    refetchInterval: 5 * 60_000,
  });

  const lancadaEm = data?.lancadaEm ?? null;
  const rag = classifyProducaoRag(lancadaEm);

  return {
    lancadaEm,
    rag,
    totalUnidades: data?.totalUnidades ?? 0,
    itens: data?.itens ?? 0,
    isLoading,
  };
}

// ─── KPIs de Estado: Logística ─────────────────────────────────────────────

export interface LogisticaEstadoKpis {
  /** Contagem de requisições por status hoje. */
  porStatus: Record<string, number>;
  isLoading: boolean;
}

export function useLogisticaEstadoKpis(): LogisticaEstadoKpis {
  const { data, isLoading } = useQuery({
    queryKey: kpisKeys.logistica(),
    queryFn: async () => {
      const hoje = new Date();
      hoje.setHours(0, 0, 0, 0);

      const { data: rows, error } = await supabase
        .from('requisicoes')
        .select('status')
        .gte('created_at', hoje.toISOString());

      if (error) throw error;

      const counts: Record<string, number> = {};
      for (const r of rows ?? []) {
        const s = (r as { status: string }).status ?? 'desconhecido';
        counts[s] = (counts[s] ?? 0) + 1;
      }
      return counts;
    },
    staleTime: 60_000,
    refetchInterval: 5 * 60_000,
  });

  return { porStatus: data ?? {}, isLoading };
}

