                  className="flex items-center gap-1.5 text-sm text-[#57715B] hover:underline
                             bg-[#57715B]/5 hover:bg-[#57715B]/10 rounded-lg px-3 py-1.5
                             transition-colors"
                >
                  <ExternalLink className="h-3.5 w-3.5" />
                  {link.label}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Ações */}
        {!isResolvido && (
          <div className="flex gap-3 mt-2">
            {!isReconhecido && (
              <Button
                variant="outline"
                className="flex-1 rounded-xl border-[#57715B]/20 text-[#57715B]
                           hover:bg-[#57715B]/10 hover:border-[#57715B]/40"
                onClick={() => onReconhecer(alerta.id).then(onClose)}
              >
                <CheckCircle2 className="h-4 w-4 mr-2" />
                Reconhecer
              </Button>
            )}
            <Button
              className="flex-1 rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white"
              onClick={() => onResolver(alerta.id).then(onClose)}
            >
              <XCircle className="h-4 w-4 mr-2" />
              Resolver
            </Button>
          </div>
        )}

        {isResolvido && (
          <div className="flex items-center gap-2 p-3 rounded-xl bg-emerald-50 dark:bg-emerald-900/20 text-sm text-emerald-700 dark:text-emerald-400">
            <CheckCircle2 className="h-4 w-4 shrink-0" />
            Alerta resolvido
          </div>
        )}
      </SheetContent>
    </Sheet>
  );
}

/**
 * @module features/gestao/ui/GestaoExceptionStrip
 *
 * Faixa de exceções (alertas abertos/reconhecidos) do setor.
 * Ordenados: critica > alta > media, depois created_at desc.
 * Nunca colapsada — management-by-exception: o problema aparece antes do número.
 * Vazio → linha discreta "Sem exceções".
 */

import { useState } from 'react';
import { AlertTriangle, ShieldAlert, Info, CheckCircle2 } from 'lucide-react';
import type { GestaoAlertaTyped, Severidade, DeepLink } from '../model/types';
import { GestaoAlertaSheet } from './GestaoAlertaSheet';

const SEV_ICON: Record<Severidade, React.ComponentType<{ className?: string }>> = {
  critica: ShieldAlert,
  alta: AlertTriangle,
  media: Info,
};

const SEV_COLOR: Record<
  Severidade,
  { dot: string; row: string; icon: string }
> = {
  critica: {
    dot: 'bg-red-500',
    row: 'hover:bg-red-50 dark:hover:bg-red-900/10',
    icon: 'text-red-500',
  },
  alta: {
    dot: 'bg-amber-500',
    row: 'hover:bg-amber-50 dark:hover:bg-amber-900/10',
    icon: 'text-amber-500',
  },
  media: {
    dot: 'bg-blue-500',
    row: 'hover:bg-blue-50 dark:hover:bg-blue-900/10',
    icon: 'text-blue-500',
  },
};

interface GestaoExceptionStripProps {
  alertas: GestaoAlertaTyped[];
  deepLinks: DeepLink[];
  onReconhecer: (id: number) => Promise<void>;
  onResolver: (id: number) => Promise<void>;
  isLoading?: boolean;
}

export function GestaoExceptionStrip({
  alertas,
  deepLinks,
  onReconhecer,
  onResolver,
  isLoading = false,
}: GestaoExceptionStripProps) {
  const [selected, setSelected] = useState<GestaoAlertaTyped | null>(null);

  const abertos = alertas.filter((a) => a.status !== 'resolvido');

  return (
    <>
      <div
        className="rounded-2xl border border-[#57715B]/10 overflow-hidden
                   bg-white/60 dark:bg-[#1A1A1A]/60 backdrop-blur-md shadow-sm"
        data-testid="exception-strip"
      >
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-2.5 bg-[#57715B]/5 border-b border-[#57715B]/10">
          <div className="flex items-center gap-2">
            <ShieldAlert className="h-4 w-4 text-[#57715B]" />
            <span className="text-xs font-bold uppercase tracking-wider text-[#57715B]">
              Exceções
            </span>
            {abertos.length > 0 && (
              <span
                className="h-5 min-w-5 px-1.5 rounded-full bg-red-500 text-white
                           text-[10px] font-bold flex items-center justify-center"
                data-testid="exception-count"
              >
                {abertos.length}
              </span>
            )}
          </div>
        </div>

        {/* Lista */}
        {isLoading ? (
          <div className="px-4 py-3 space-y-2 animate-pulse">
            {[1, 2].map((i) => (
              <div key={i} className="h-8 rounded-lg bg-[#57715B]/5" />
            ))}
          </div>
        ) : abertos.length === 0 ? (
          <div
            className="flex items-center gap-2 px-4 py-3 text-sm text-muted-foreground"
            data-testid="exception-strip-empty"
          >
            <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0" />
            <span>Sem exceções</span>
          </div>
        ) : (
          <ul className="divide-y divide-[#57715B]/5">
            {abertos.map((alerta) => {
              const sev = alerta.severidade as Severidade;
              const cfg = SEV_COLOR[sev] ?? SEV_COLOR.media;
              const Icon = SEV_ICON[sev] ?? Info;

              return (
                <li key={alerta.id}>
                  <button
                    className={`w-full text-left flex items-start gap-3 px-4 py-3
                                transition-colors ${cfg.row}`}
                    onClick={() => setSelected(alerta)}
                    data-testid="exception-row"
                    data-severity={sev}
                  >
                    {/* Indicador cromático + ícone redundante */}
                    <div className="flex items-center gap-1.5 shrink-0 mt-0.5">
                      <span
                        className={`h-2 w-2 rounded-full shrink-0 ${cfg.dot}`}
                        aria-hidden="true"
                      />
                      <Icon className={`h-3.5 w-3.5 ${cfg.icon}`} aria-hidden="true" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF] truncate">
                        {alerta.titulo}
                      </p>
                      {alerta.status === 'reconhecido' && (
                        <span className="text-[10px] text-[#57715B] uppercase tracking-wide font-semibold">
                          reconhecido
                        </span>
                      )}
                    </div>
                    <span className="text-[11px] text-muted-foreground shrink-0 mt-0.5 font-mono">
                      {new Date(alerta.created_at).toLocaleTimeString('pt-BR', {
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                    </span>
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </div>

      <GestaoAlertaSheet
        alerta={selected}
        deepLinks={deepLinks}
        onClose={() => setSelected(null)}
        onReconhecer={onReconhecer}
        onResolver={onResolver}
      />
    </>
  );
}

/**
 * @module features/gestao/ui/GestaoKpiHeader
