/**
 * @module features/gestao/ui/GestaoEventFeed
 *
 * Timeline realtime de `eventos_operacionais` de um setor.
 * - Prepend de novos eventos com debounce 2s (via useEventosFeed)
 * - Paginação cursor-based (botão "carregar anteriores")
 * - Renderers pt-BR por tipo_evento
 * - Tap em evento → bottom sheet com payload + deep-link para referência N0
 */

import { useState } from 'react';
import { formatDistanceToNow } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import {
  Truck,
  Tag,
  Package,
  TrendingDown,
  TrendingUp,
  AlertTriangle,
  RefreshCw,
  ClipboardList,
  Activity,
  ChevronDown,
  ExternalLink,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from '@/shared/ui/sheet';
import { Button } from '@/shared/ui/button';
import { useEventosFeed } from '../model/useEventosFeed';
import type { Setor, EventoOperacional } from '../model/types';

// ─── Mapa de renderers de tipo_evento ──────────────────────────────────────

type EventRenderer = (ev: EventoOperacional) => {
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  iconClass: string;
  detail: string;
  deepLinkPath?: string;
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const p = (ev: EventoOperacional) => (ev.payload ?? {}) as Record<string, any>;

const RENDERERS: Record<string, EventRenderer> = {
  'requisicao.criada': (ev) => ({
    label: `Req. criada — ${p(ev).loja_solicitante ?? ''}`,
    icon: ClipboardList,
    iconClass: 'text-[#57715B]',
    detail: `Status: ${p(ev).status ?? '—'}`,
    deepLinkPath: '/requisicao',
  }),
  'requisicao.status_alterada': (ev) => {
    const statusNovo = (p(ev).status_novo as string) ?? '';
    const statusAnt = (p(ev).status_anterior as string) ?? '';
    return {
      label: `Req. → ${statusNovo}`,
      icon: Truck,
      iconClass: 'text-blue-500',
      detail: `${statusAnt} → ${statusNovo}`,
      deepLinkPath: '/requisicao',
    };
  },
  'etiqueta.bipada': (ev) => ({
    label: `Etiqueta bipada — ${p(ev).etapa ?? ''}`,
    icon: Tag,
    iconClass: 'text-violet-500',
    detail: `Tipo: ${p(ev).tipo ?? '—'} · Status: ${p(ev).status_novo ?? '—'}`,
    deepLinkPath: ev.referencia_id ? `/etiquetas/${ev.referencia_id}` : undefined,
  }),
  'expedicao.log': (ev) => ({
    label: (p(ev).title as string) ?? 'Expedição: log',
    icon: Truck,
    iconClass: 'text-[#57715B]',
    detail: `Tipo: ${p(ev).type ?? '—'}`,
    deepLinkPath: '/logistica/control-tower',
  }),
  'producao.lancada': (ev) => ({
    label: `Produção lançada: ${p(ev).total_unidades ?? '?'} un`,
    icon: Package,
    iconClass: 'text-emerald-600',
    detail: `Itens: ${typeof p(ev).itens === 'number' ? p(ev).itens : (Array.isArray(p(ev).itens) ? (p(ev).itens as unknown[]).length : '?')}`,
    deepLinkPath: '/producao-diaria',
  }),
  'producao.ajustada': (ev) => ({
    label: 'Produção ajustada',
    icon: RefreshCw,
    iconClass: 'text-amber-500',
    detail: `Data: ${p(ev).data ?? '—'}`,
    deepLinkPath: '/producao-diaria',
  }),
  'estoque.movimentacao': (ev) => ({
    label: `Movimentação — ${p(ev).tipo_movimentacao ?? ''}`,
    icon: Activity,
    iconClass: 'text-[#57715B]',
    detail: `Qtd: ${p(ev).quantidade ?? '—'}`,
    deepLinkPath: '/movimentacoes',
  }),
  'estoque.ruptura': (ev) => ({
    label: `Ruptura: ${p(ev).produto_nome ?? ''}`,
    icon: TrendingDown,
    iconClass: 'text-red-500',
    detail: `Quantidade: ${p(ev).quantidade_atual ?? 0}`,
    deepLinkPath: '/movimentacoes',
  }),
  'estoque.abaixo_minimo': (ev) => ({
    label: `Abaixo do mínimo: ${p(ev).produto_nome ?? ''}`,
    icon: AlertTriangle,
    iconClass: 'text-amber-500',
    detail: `Atual: ${p(ev).quantidade_atual ?? '—'} / Mín: ${p(ev).quantidade_minima ?? '—'}`,
    deepLinkPath: '/produtos',
  }),
  'estoque.minmax_recalculado': (ev) => ({
    label: 'Min/Max recalculado',
    icon: TrendingUp,
    iconClass: 'text-[#57715B]',
    detail: `${p(ev).pares_atualizados ?? '?'} pares atualizados`,
    deepLinkPath: '/produtos',
  }),
};

function renderEvento(ev: EventoOperacional): ReturnType<EventRenderer> {
  const fn = RENDERERS[ev.tipo_evento];
  if (fn) return fn(ev);
  // Fallback genérico
  return {
    label: ev.tipo_evento,
    icon: Activity,
    iconClass: 'text-muted-foreground',
    detail: '',
  };
}

// ─── Sheet de detalhe do evento ─────────────────────────────────────────────

function EventDetailSheet({
  evento,
  onClose,
}: {
  evento: EventoOperacional | null;
  onClose: () => void;
}) {
  const navigate = useNavigate();
  if (!evento) return null;
  const rendered = renderEvento(evento);
  const Icon = rendered.icon;

  return (
    <Sheet open={!!evento} onOpenChange={(open) => { if (!open) onClose(); }}>
      <SheetContent
        side="bottom"
        className="rounded-t-[2rem] bg-white/95 dark:bg-zinc-900/95 backdrop-blur-xl
                   border-t border-[#57715B]/10 px-5 pt-5 pb-[calc(1.5rem+env(safe-area-inset-bottom))]
                   max-h-[80dvh] overflow-y-auto"
      >
        <SheetHeader className="text-left mb-4">
          <div className="flex items-start gap-3">
            <div className={`mt-0.5 shrink-0 ${rendered.iconClass}`}>
              <Icon className="h-5 w-5" />
            </div>
            <SheetTitle className="text-base font-bold text-[#2D362E] dark:text-[#E6DCCF] leading-snug">
              {rendered.label}
            </SheetTitle>
          </div>
        </SheetHeader>

        <div className="space-y-3 text-sm text-[#2D362E]/80 dark:text-[#E6DCCF]/80">
          <div className="flex justify-between">
            <span className="text-muted-foreground">Hora</span>
            <span className="font-mono text-xs">
              {new Date(evento.criado_em).toLocaleString('pt-BR', {
                day: '2-digit',
                month: '2-digit',
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
              })}
            </span>
          </div>
          {evento.ator_nome && (
            <div className="flex justify-between">
              <span className="text-muted-foreground">Ator</span>
              <span>{evento.ator_nome}</span>
            </div>
          )}
          {evento.referencia_tipo && (
            <div className="flex justify-between">
              <span className="text-muted-foreground">Referência</span>
              <span className="text-xs font-mono">
                {evento.referencia_tipo}:{evento.referencia_id ?? '?'}
              </span>
            </div>
          )}
          {rendered.detail && (
            <div className="flex justify-between">
              <span className="text-muted-foreground">Detalhe</span>
              <span>{rendered.detail}</span>
            </div>
          )}
          {/* Payload raw (só se houver campos extras) */}
          {evento.payload && Object.keys(evento.payload).length > 0 && (
            <details className="mt-2">
              <summary className="text-xs text-muted-foreground cursor-pointer hover:text-[#57715B]">
                Payload (raw)
              </summary>
              <pre className="mt-2 text-[11px] bg-[#57715B]/5 rounded-lg p-3 overflow-x-auto font-mono text-[#2D362E]/70 dark:text-[#E6DCCF]/70">
                {JSON.stringify(evento.payload, null, 2)}
              </pre>
            </details>
          )}
        </div>

        {rendered.deepLinkPath && (
          <Button
            className="mt-5 w-full rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white"
            onClick={() => {
              navigate(rendered.deepLinkPath!);
              onClose();
            }}
          >
            <ExternalLink className="h-4 w-4 mr-2" />
            Ir para a tela
          </Button>
        )}
      </SheetContent>
    </Sheet>
  );
}

// ─── Feed principal ─────────────────────────────────────────────────────────

interface GestaoEventFeedProps {
  setor: Setor;
  lojaId: number | null;
}

export function GestaoEventFeed({ setor, lojaId }: GestaoEventFeedProps) {
  const { eventos, isLoading, hasMore, loadMore } = useEventosFeed({
    setor,
    lojaId,
  });
  const [selected, setSelected] = useState<EventoOperacional | null>(null);

  return (
    <>
      <div
        className="rounded-2xl border border-[#57715B]/10 overflow-hidden
                   bg-white/60 dark:bg-[#1A1A1A]/60 backdrop-blur-md shadow-sm"
        aria-label="Feed de eventos ao vivo"
      >
        {/* Header */}
        <div className="flex items-center gap-2 px-4 py-2.5 bg-[#57715B]/5 border-b border-[#57715B]/10">
          <span className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse" aria-hidden="true" />
          <span className="text-xs font-bold uppercase tracking-wider text-[#57715B]">
            Ao Vivo
          </span>
        </div>

        {/* Lista */}
        {isLoading && eventos.length === 0 ? (
          <div className="px-4 py-3 space-y-3 animate-pulse">
            {[1, 2, 3].map((i) => (
              <div key={i} className="flex gap-3">
                <div className="h-4 w-12 rounded bg-[#57715B]/5" />
                <div className="h-4 flex-1 rounded bg-[#57715B]/5" />
              </div>
            ))}
          </div>
        ) : eventos.length === 0 ? (
          <div className="px-4 py-8 text-center text-sm text-muted-foreground">
            Nenhum evento hoje
          </div>
        ) : (
          <ul className="divide-y divide-[#57715B]/5">
            {eventos.map((ev) => {
              const rendered = renderEvento(ev);
              const Icon = rendered.icon;
              return (
                <li key={ev.id}>
                  <button
                    className="w-full text-left flex items-start gap-3 px-4 py-3
                               hover:bg-[#57715B]/5 transition-colors group"
                    onClick={() => setSelected(ev)}
                    data-testid="feed-event-row"
                  >
                    {/* Hora */}
                    <span className="text-[11px] text-muted-foreground font-mono shrink-0 mt-0.5 w-10">
                      {new Date(ev.criado_em).toLocaleTimeString('pt-BR', {
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                    </span>
                    {/* Ícone */}
                    <span className={`mt-0.5 shrink-0 ${rendered.iconClass}`}>
                      <Icon className="h-3.5 w-3.5" aria-hidden="true" />
                    </span>
                    {/* Conteúdo */}
                    <div className="flex-1 min-w-0">
                      <p className="text-sm text-[#2D362E] dark:text-[#E6DCCF] leading-snug">
                        {rendered.label}
                      </p>
                      {ev.ator_nome && (
                        <p className="text-[11px] text-muted-foreground truncate">
                          {ev.ator_nome}
                          {' · '}
                          {formatDistanceToNow(new Date(ev.criado_em), {
                            addSuffix: true,
                            locale: ptBR,
                          })}
                        </p>
                      )}
                    </div>
                  </button>
                </li>
              );
            })}
          </ul>
        )}

        {/* Carregar anteriores */}
        {hasMore && (
          <div className="border-t border-[#57715B]/5 px-4 py-2">
            <button
              className="w-full flex items-center justify-center gap-1.5 text-xs
                         text-muted-foreground hover:text-[#57715B] transition-colors py-1.5"
              onClick={loadMore}
            >
              <ChevronDown className="h-3.5 w-3.5" />
              carregar anteriores
            </button>
          </div>
        )}
      </div>

      <EventDetailSheet evento={selected} onClose={() => setSelected(null)} />
    </>
  );
}

/**
 * @module features/gestao/ui/GestaoAlertasBell
 *
 * Sino realtime de alertas de gestão.
 * Badge = count de alertas status='aberto' (todos os setores visíveis pelo usuário).
 * Dropdown com últimos 10 + link para o painel do setor.
 *
 * Renderizado no header ao lado do NotificationBell do RH.
 * Visível para quem tem qualquer view_gestao_* OU isAdmin().
 */

import { BellRing, AlertTriangle, ShieldAlert, Info, ExternalLink } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from '@/shared/ui/dropdown-menu';
import { Button } from '@/shared/ui/button';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { useGestaoAlertasBell } from '../model/useGestaoAlertas';
import { getAllGestaoPermissions } from '../model/setorConfig';
import type { GestaoAlertaTyped, Severidade, Setor } from '../model/types';

const SEV_ICON: Record<Severidade, React.ComponentType<{ className?: string }>> = {
  critica: ShieldAlert,
  alta: AlertTriangle,
  media: Info,
};

const SEV_COLOR: Record<Severidade, string> = {
  critica: 'text-red-500',
  alta: 'text-amber-500',
  media: 'text-blue-500',
};

const SETOR_PATH: Record<Setor, string> = {
  logistica: '/gestao/logistica',
  producao: '/gestao/producao',
  estoque: '/gestao/estoque',
};

function AlertaRow({ alerta, onNavigate }: { alerta: GestaoAlertaTyped; onNavigate: () => void }) {
  const sev = alerta.severidade as Severidade;
  const Icon = SEV_ICON[sev] ?? Info;
  const colorClass = SEV_COLOR[sev] ?? 'text-muted-foreground';
  const navigate = useNavigate();
  const destino = SETOR_PATH[alerta.setor as Setor];

  return (
    <button
      className="w-full text-left flex items-start gap-2 px-3 py-2.5
                 hover:bg-[#57715B]/5 transition-colors"
      onClick={() => {
        if (destino) navigate(destino);
        onNavigate();
      }}
    >
      <Icon className={`h-4 w-4 mt-0.5 shrink-0 ${colorClass}`} />
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF] truncate">
          {alerta.titulo}
        </p>
        <p className="text-[11px] text-muted-foreground truncate">
          {alerta.setor} ·{' '}
          {new Date(alerta.created_at).toLocaleTimeString('pt-BR', {
            hour: '2-digit',
            minute: '2-digit',
          })}
        </p>
      </div>
    </button>
  );
}

export function GestaoAlertasBell() {
  const { hasPermission, isAdmin } = usePermissions();
  const navigate = useNavigate();

  const gestaoPerms = getAllGestaoPermissions();
  const canView = isAdmin() || gestaoPerms.some((p) => hasPermission(p));

  const { count, isLoading, recentAlertas } = useGestaoAlertasBell();

  // Não renderizar se o usuário não tem acesso a nenhum setor de gestão
  if (!canView) return null;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className="relative h-9 w-9 rounded-xl hover:bg-[#57715B]/10"
          aria-label={`Alertas de gestão${count > 0 ? ` (${count} abertos)` : ''}`}
        >
          <BellRing className="h-5 w-5 text-[#57715B] dark:text-[#E6DCCF]" />
          {count > 0 && (
            <span
              className="absolute -top-0.5 -right-0.5 h-4 min-w-4 px-1 rounded-full
                         bg-amber-500 text-white text-[10px] font-bold
                         flex items-center justify-center"
              aria-hidden="true"
            >
              {count > 9 ? '9+' : count}
            </span>
          )}
        </Button>
      </DropdownMenuTrigger>

      <DropdownMenuContent
        align="end"
        className="w-80 max-h-[480px] overflow-y-auto rounded-2xl border-[#57715B]/10
                   bg-white/95 dark:bg-zinc-900/95 backdrop-blur-xl p-0"
      >
        {/* Header */}
        <div className="flex items-center justify-between p-3 border-b border-[#57715B]/10">
          <div>
            <p className="font-bold text-sm text-[#2D362E] dark:text-[#E6DCCF]">
