            </p>
            {count > 0 && (
              <p className="text-xs text-amber-600">{count} abertos</p>
            )}
          </div>
        </div>

        {/* Lista de alertas */}
        {isLoading ? (
          <div className="px-3 py-4 space-y-2 animate-pulse">
            {[1, 2].map((i) => (
              <div key={i} className="h-10 rounded-lg bg-[#57715B]/5" />
            ))}
          </div>
        ) : recentAlertas.length === 0 ? (
          <div className="py-8 text-center text-sm text-muted-foreground">
            Sem alertas abertos
          </div>
        ) : (
          <div className="divide-y divide-[#57715B]/5">
            {recentAlertas.map((a) => (
              <AlertaRow key={a.id} alerta={a} onNavigate={() => {}} />
            ))}
          </div>
        )}

        {/* Links para painéis */}
        <div className="border-t border-[#57715B]/10 p-2 flex flex-col gap-1">
          {(['logistica', 'producao', 'estoque'] as Setor[])
            .filter((s) => isAdmin() || hasPermission(`view_gestao_${s}`))
            .map((s) => (
              <button
                key={s}
                className="flex items-center gap-1.5 text-xs text-[#57715B] hover:underline
                           rounded-lg px-2 py-1.5 hover:bg-[#57715B]/5 transition-colors capitalize"
                onClick={() => navigate(SETOR_PATH[s])}
              >
                <ExternalLink className="h-3 w-3" />
                Painel {s}
              </button>
            ))}
        </div>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * @module features/gestao/ui/GestaoSetor.page
 *
 * Shell único dos painéis de gestão operacional N1, parametrizado por setor.
 * Ordem vertical mobile: exceções → KPIs → feed.
 * Desktop: 2 colunas (exceções+KPIs | feed).
 *
 * Layout: MommaPageLayout + glassmorphism verde sage, conforme design-system.md.
 */

import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
import { useStore } from '@/shared/contexts/StoreContext';
import { useGestaoAlertas } from '../model/useGestaoAlertas';
import { getSetorConfig } from '../model/setorConfig';
import { GestaoExceptionStrip } from './GestaoExceptionStrip';
import { GestaoKpiHeader } from './GestaoKpiHeader';
import { GestaoEventFeed } from './GestaoEventFeed';
import type { Setor } from '../model/types';

interface GestaoSetorPageProps {
  setor: Setor;
}

export function GestaoSetorPage({ setor }: GestaoSetorPageProps) {
  const config = getSetorConfig(setor);
  const { selectedStore } = useStore();
  const lojaId = selectedStore?.id ?? null;

  const { alertas, isLoading: alertasLoading, reconhecer, resolver } =
    useGestaoAlertas(setor);

  const Icon = config.icon;

  return (
    <MommaPageLayout>
      <div className="flex flex-col gap-4 px-4 pt-4 pb-6 max-w-5xl mx-auto w-full">
        {/* ─── Header da página ─────────────────────────────────────────── */}
        <div className="flex items-center gap-3">
          <div className="rounded-2xl bg-[#57715B]/10 p-2.5 shrink-0">
            <Icon className="h-5 w-5 text-[#57715B]" />
          </div>
          <div>
            <h1 className="text-2xl font-bold tracking-tight font-serif text-[#2D362E] dark:text-[#E6DCCF]">
              Gestão · {config.titulo}
            </h1>
            <p className="text-xs uppercase tracking-widest text-muted-foreground">
              {config.subtitulo}
              {selectedStore && (
                <>
                  {' '}· <span className="font-medium">{selectedStore.shortName}</span>
                </>
              )}
            </p>
          </div>
        </div>

        {/* ─── Layout responsivo ────────────────────────────────────────── */}
        {/* Mobile: coluna única — desktop: 2 colunas */}
        <div className="grid grid-cols-1 md:grid-cols-[1fr_1.4fr] gap-4">
          {/* Coluna esquerda: exceções + KPIs */}
          <div className="flex flex-col gap-4">
            {/* 1. Exceções — sempre primeiro, nunca colapsado */}
            <GestaoExceptionStrip
              alertas={alertas}
              deepLinks={config.deepLinks}
              onReconhecer={reconhecer}
              onResolver={resolver}
              isLoading={alertasLoading}
