/**
 * @module features/gestao/model/setorConfig.test
 *
 * Verifica que o registry de setores está completo e as permissions corretas.
 */

import { describe, it, expect } from 'vitest';
import {
  getSetorConfig,
  SETORES_ATIVOS,
  getAllGestaoPermissions,
} from './setorConfig';
import type { Setor } from './types';

describe('setorConfig — registry completo', () => {
  it('SETORES_ATIVOS contém os 3 setores da 1ª onda', () => {
    expect(SETORES_ATIVOS).toHaveLength(3);
    expect(SETORES_ATIVOS).toContain('logistica');
    expect(SETORES_ATIVOS).toContain('producao');
    expect(SETORES_ATIVOS).toContain('estoque');
  });

  it('cada setor tem config completa', () => {
    for (const setor of SETORES_ATIVOS) {
      const cfg = getSetorConfig(setor);
      expect(cfg.setor).toBe(setor);
      expect(cfg.permission).toBeTruthy();
      expect(cfg.titulo).toBeTruthy();
      expect(cfg.subtitulo).toBeTruthy();
      expect(cfg.icon).toBeDefined();
      expect(cfg.KpisComponent).toBeDefined();
      expect(Array.isArray(cfg.deepLinks)).toBe(true);
      expect(cfg.deepLinks.length).toBeGreaterThan(0);
    }
  });

  it('permissions seguem o padrão view_gestao_<setor>', () => {
    for (const setor of SETORES_ATIVOS) {
      const cfg = getSetorConfig(setor);
      expect(cfg.permission).toBe(`view_gestao_${setor}`);
    }
  });

  it('getAllGestaoPermissions retorna 3 permissions distintas', () => {
    const perms = getAllGestaoPermissions();
    expect(perms).toHaveLength(3);
    expect(new Set(perms).size).toBe(3);
    expect(perms).toContain('view_gestao_logistica');
    expect(perms).toContain('view_gestao_producao');
    expect(perms).toContain('view_gestao_estoque');
  });

  it('deep-links têm label e path preenchidos', () => {
    for (const setor of SETORES_ATIVOS) {
      const cfg = getSetorConfig(setor);
      for (const link of cfg.deepLinks) {
        expect(link.label).toBeTruthy();
        expect(link.path).toMatch(/^\//);
      }
    }
  });

  it('getSetorConfig lança para setor desconhecido', () => {
    expect(() => getSetorConfig('invalido' as Setor)).toThrow();
  });
});

/**
 * @module features/gestao/model/useGestaoKpis.test
 *
 * Testes unitários para funções puras do hook de KPIs.
 * Foca em classifyProducaoRag (determinística, testável sem mocks).
 */

import { describe, it, expect } from 'vitest';
import { classifyProducaoRag } from './useGestaoKpis';

describe('classifyProducaoRag', () => {
  it('retorna "verde" quando a produção foi lançada (independente da hora)', () => {
    const lancadaEm = new Date().toISOString();
    const agora = new Date();
    agora.setHours(15, 0, 0, 0);
    expect(classifyProducaoRag(lancadaEm, agora)).toBe('verde');
  });

  it('retorna "verde" mesmo que lançada depois das 12h', () => {
    const lancadaEm = new Date().toISOString();
    const agora = new Date();
    agora.setHours(18, 0, 0, 0);
    expect(classifyProducaoRag(lancadaEm, agora)).toBe('verde');
  });

  it('retorna "ambar" quando não lançada e hora < 12:00', () => {
    const agora = new Date();
    agora.setHours(9, 30, 0, 0);
    expect(classifyProducaoRag(null, agora)).toBe('ambar');
  });

  it('retorna "ambar" às 11:59', () => {
    const agora = new Date();
    agora.setHours(11, 59, 0, 0);
    expect(classifyProducaoRag(null, agora)).toBe('ambar');
  });

  it('retorna "vermelho" quando não lançada e hora >= 12:00', () => {
    const agora = new Date();
    agora.setHours(12, 0, 0, 0);
    expect(classifyProducaoRag(null, agora)).toBe('vermelho');
  });

  it('retorna "vermelho" à tarde', () => {
    const agora = new Date();
    agora.setHours(16, 45, 0, 0);
    expect(classifyProducaoRag(null, agora)).toBe('vermelho');
  });

  it('retorna "vermelho" à noite', () => {
    const agora = new Date();
    agora.setHours(21, 0, 0, 0);
    expect(classifyProducaoRag(null, agora)).toBe('vermelho');
  });
});

/**
 * @module features/gestao/ui/GestaoExceptionStrip.test
 *
 * Testa:
 * - Estado vazio: "Sem exceções" visível
 * - Ordenação por severidade (critica > alta > media)
 * - Renderização de badge de contagem
 */

import { render, screen } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { GestaoExceptionStrip } from './GestaoExceptionStrip';
import type { GestaoAlertaTyped, DeepLink } from '../model/types';

// GestaoAlertaSheet usa useNavigate — mockar react-router-dom
vi.mock('react-router-dom', () => ({
  useNavigate: () => vi.fn(),
  Sheet: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
}));

// Mockar Sheet do shadcn (bottom sheet)
vi.mock('@/shared/ui/sheet', () => ({
  Sheet: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
  SheetContent: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
  SheetHeader: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
  SheetTitle: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
  SheetDescription: ({ children, asChild }: { children: React.ReactNode; asChild?: boolean }) =>
    asChild ? <>{children}</> : <div>{children}</div>,
}));

function makeAlerta(
  id: number,
  severidade: 'critica' | 'alta' | 'media',
  status: 'aberto' | 'reconhecido' = 'aberto',
  hoursAgo = 1,
): GestaoAlertaTyped {
  const ts = new Date(Date.now() - hoursAgo * 3600 * 1000).toISOString();
  return {
    id,
    setor: 'logistica',
    severidade,
    status,
    titulo: `Alerta ${id} - ${severidade}`,
    mensagem: `Mensagem do alerta ${id}`,
    dedup_key: `key-${id}`,
    loja_id: null,
    expectativa_id: null,
    reconhecido_por: null,
    reconhecido_em: null,
    resolvido_em: null,
    resolucao: null,
    evento_gatilho_id: null,
    created_at: ts,
  };
}

const noopDeepLinks: DeepLink[] = [{ label: 'Torre', path: '/logistica/control-tower' }];
const noop = async () => {};

describe('GestaoExceptionStrip — estado vazio', () => {
  it('exibe "Sem exceções" quando não há alertas', () => {
    render(
      <GestaoExceptionStrip
        alertas={[]}
        deepLinks={noopDeepLinks}
        onReconhecer={noop}
        onResolver={noop}
      />,
    );
    expect(screen.getByTestId('exception-strip-empty')).toBeInTheDocument();
    expect(screen.getByText('Sem exceções')).toBeInTheDocument();
  });

  it('não exibe badge de contagem quando vazio', () => {
    render(
      <GestaoExceptionStrip
        alertas={[]}
        deepLinks={noopDeepLinks}
        onReconhecer={noop}
        onResolver={noop}
      />,
    );
    expect(screen.queryByTestId('exception-count')).not.toBeInTheDocument();
  });
});

describe('GestaoExceptionStrip — lista e ordenação', () => {
  it('exibe badge com contagem de alertas ativos', () => {
    const alertas = [
      makeAlerta(1, 'media'),
      makeAlerta(2, 'alta'),
      makeAlerta(3, 'critica'),
    ];
    render(
      <GestaoExceptionStrip
        alertas={alertas}
        deepLinks={noopDeepLinks}
        onReconhecer={noop}
        onResolver={noop}
      />,
    );
    expect(screen.getByTestId('exception-count')).toHaveTextContent('3');
  });

  it('ordena critica antes de alta antes de media', () => {
    // Alertas inseridos em ordem media → alta → critica (desordenada)
    const alertas = [
      makeAlerta(1, 'media'),
      makeAlerta(2, 'alta'),
      makeAlerta(3, 'critica'),
    ];
    render(
      <GestaoExceptionStrip
        alertas={alertas}
        deepLinks={noopDeepLinks}
        onReconhecer={noop}
        onResolver={noop}
      />,
    );
    const rows = screen.getAllByTestId('exception-row');
    expect(rows).toHaveLength(3);
    // Primeira row deve ser critica (id=3), depois alta (id=2), depois media (id=1)
    expect(rows[0]).toHaveAttribute('data-severity', 'critica');
    expect(rows[1]).toHaveAttribute('data-severity', 'alta');
    expect(rows[2]).toHaveAttribute('data-severity', 'media');
  });

  it('não exibe alertas resolvidos', () => {
    const alertas = [
      makeAlerta(1, 'alta', 'aberto'),
      makeAlerta(2, 'critica', 'aberto'),
      { ...makeAlerta(3, 'critica'), status: 'resolvido' as const },
    ];
    render(
      <GestaoExceptionStrip
        alertas={alertas}
        deepLinks={noopDeepLinks}
        onReconhecer={noop}
        onResolver={noop}
      />,
    );
    const rows = screen.getAllByTestId('exception-row');
    expect(rows).toHaveLength(2);
  });
});

